package com.example.starter.race.domain;

/**
 * 组别状态：
 * OPEN-开放，可迁入迁出与接收新申请；
 * SEALED-已封榜冻结，封榜快照仅固化封榜时刻所属该组别的在赛选手，后续不追溯重写。
 */
public enum CategoryStatus {
    OPEN,
    SEALED
}

package com.example.starter.race.domain;

/**
 * 组别重分申请状态：
 * PENDING-待审批；
 * APPROVED-已批准（参赛者组别已在批准事务内迁移）；
 * REJECTED-已拒绝（不改变任何成绩）。
 */
public enum ReclassRequestStatus {
    PENDING,
    APPROVED,
    REJECTED
}

package com.example.starter.race.persistence;

import com.example.starter.race.domain.CategoryStatus;

/**
 * race_category 表行记录。
 *
 * @param raceId       所属赛事ID
 * @param categoryCode 组别代码，赛事内唯一
 * @param capacity     组别容量（在赛人数上限）；已退赛者不占容量
 * @param status       组别状态：OPEN / SEALED
 * @param createdAt    创建时间，Unix毫秒时间戳
 * @param sealedAt     组别封榜时间，Unix毫秒时间戳；未封榜为 null
 */
public record CategoryRow(
        String raceId,
        String categoryCode,
        int capacity,
        CategoryStatus status,
        long createdAt,
        Long sealedAt
) {
}

package com.example.starter.race.persistence;

import java.util.List;

/**
 * 组别封榜快照：头表行加全部固化条目。
 *
 * @param raceId       所属赛事ID
 * @param categoryCode 组别代码
 * @param sealedAt     组别封榜时间，Unix毫秒时间戳
 * @param entries      封榜时刻所属该组别的在赛选手成绩条目，按展示顺序排列
 */
public record CategorySnapshotRow(
        String raceId,
        String categoryCode,
        long sealedAt,
        List<CategorySnapshotEntryRow> entries
) {
}

