        String categoryCode,
        boolean withdrawn,
        Long withdrawnAt,
        long createdAt,
        long updatedAt
) {
}

package com.example.starter.race.api;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Positive;

/**
 * 登记选手请求；不传 finishTimeMs 时该选手计时缺失（UNTIMED）。
 *
 * @param bib             参赛号，赛事内唯一
 * @param finishTimeMs    原始完赛耗时（毫秒，1~86400000）；可空表示暂未计时
 * @param category        初始所属组别代码；可空表示未分组，组别必须已存在且未封榜、容量未满
 * @param expectedVersion 客户端所见赛事版本，服务端据此做乐观并发控制
 * @param requestId       全局唯一请求ID（幂等键）
 */
public record RegisterRunnerRequest(
        @NotBlank String bib,
        @Positive Long finishTimeMs,
        String category,
        @NotNull Integer expectedVersion,
        @NotBlank String requestId
) {

    /** 兼容旧调用：不指定初始组别（未分组）。 */
    public RegisterRunnerRequest(String bib, Long finishTimeMs, Integer expectedVersion,
            String requestId) {
        this(bib, finishTimeMs, null, expectedVersion, requestId);
    }
}

package com.example.starter.race.api;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Positive;

/**
 * 新建组别请求。
 *
 * @param categoryCode    组别代码，赛事内唯一
 * @param capacity        组别容量（在赛人数上限，>=1）；已退赛者不占容量
 * @param expectedVersion 客户端所见赛事版本，服务端据此做乐观并发控制
 * @param requestId       全局唯一请求ID（幂等键）
 */
public record CreateCategoryRequest(
        @NotBlank String categoryCode,
        @Positive int capacity,
        @NotNull Integer expectedVersion,
        @NotBlank String requestId
) {
}

package com.example.starter.race.api;

import com.example.starter.race.domain.CategoryStatus;
import com.fasterxml.jackson.annotation.JsonInclude;

/**
 * 组别信息响应。
 *
 * @param raceId       所属赛事ID
 * @param categoryCode 组别代码
 * @param capacity     组别容量（在赛人数上限）
 * @param activeCount  当前在赛（未退赛）人数
 * @param status       组别状态：OPEN / SEALED
 * @param createdAt    创建时间，Unix毫秒时间戳
 * @param sealedAt     组别封榜时间，Unix毫秒时间戳；未封榜为 null
 */
@JsonInclude(JsonInclude.Include.NON_NULL)
public record CategoryResponse(
        String raceId,
        String categoryCode,
        int capacity,
        int activeCount,
        CategoryStatus status,
        long createdAt,
        Long sealedAt
) {
}

package com.example.starter.race.api;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;

/**
 * 提交组别重分申请请求。
 *
 * @param bib             申请参赛者参赛号
 * @param targetCategory  目标组别代码，必须已存在且未封榜
 * @param reason          申请理由（1~512字符）
 * @param expectedVersion 客户端所见赛事版本，服务端据此做乐观并发控制
 * @param requestId       全局唯一请求ID（幂等键，兼作申请ID）
 */
public record ReclassApplyRequest(
        @NotBlank String bib,
        @NotBlank String targetCategory,
        @NotBlank @Size(max = 512) String reason,
        @NotNull Integer expectedVersion,
        @NotBlank String requestId
) {
}

