        assertThat(snapshotAgain.entries()).extracting(ResultEntryResponse::bib)
                .containsExactly("a", "b");
        assertThat(snapshotAgain.entries().get(0).totalTimeMs()).isEqualTo(1000L);
    }

    @Test
