    @Test
    void 批准失败不占键_同键修正后成功() {
        createRace();
        createCategory("A", 10);
        createCategory("B", 1);
        register("a", 1000L, "A");
        register("c", 1500L, "B");
        String appId = apply("a", "B");

        // B 容量被 c 占满：批准 422，失败不占键
        assertThatThrownBy(() -> raceService.approveReclass(RACE, new ApproveReclassRequest(
